from fastapi import APIRouter, Query
from typing import Optional
import base64, json

router = APIRouter()

def encode_cursor(last_id: int) -> str:
    return base64.urlsafe_b64encode(json.dumps({'id': last_id}).encode()).decode()

def decode_cursor(c: str) -> int:
    return json.loads(base64.urlsafe_b64decode(c.encode()))['id']

@router.get('/{{table_name}}')
async def list_items(cursor: Optional[str] = None, limit: int = Query(20, le=100)):
    after_id = decode_cursor(cursor) if cursor else 0
    rows = []  # await db.fetch('SELECT * FROM {{table_name}} WHERE id > $1 ORDER BY id LIMIT $2', after_id, limit)
    next_cursor = encode_cursor(rows[-1]['id']) if len(rows) == limit else None
    return {'data': rows, 'next_cursor': next_cursor}
